package com.vandorlabs.neoforge.canopy;

import com.vandorlabs.animation.*;
import net.minecraft.core.BlockPos;

public final class CanopyAnimationChecks {
    private static int checks;private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Canopy animation "+text);}
    private static void pose(double actual,double expected,String text){need(actual==expected,text+" expected="+expected+" actual="+actual);}
    public static void main(String[] args){
        var animation=new CanopyAnimation();pose(animation.sample(false,false,0,0),0,"closed initial");pose(animation.sample(true,false,0,10),0,"target begins at current visual");pose(animation.sample(true,false,0,18),.5,"linear half progress before authored easing");pose(animation.sample(false,false,0,18),.5,"reverse without snap");pose(animation.sample(false,false,0,22),.25,"constant reversal speed");pose(animation.sample(false,true,.875,23),.875,"authoritative wait starts at retained pose");pose(animation.sample(false,true,.875,100),.875,"wait does not consume motion time");pose(animation.sample(false,false,.875,100),.875,"resume recaptures authoritative wait endpoint");pose(animation.sample(false,false,.875,104),.625,"resume advances linearly");pose(animation.sample(true,false,.875,104),.625,"reverse while resuming");pose(animation.sample(true,false,0,110),1,"stale progress packet does not restart");pose(animation.sample(true,false,0,-20),1,"clock correction does not reverse motion");
        var clock=new VisualClock();double time=clock.sample(1_000_000_000L,false);var paused=new CanopyAnimation();paused.sample(false,false,0,time);paused.sample(true,false,0,time);pose(paused.sample(true,false,0,clock.sample(1_400_000_000L,false)),.5,"eight visual ticks");double frozen=clock.sample(1_400_000_000L,true);pose(paused.sample(true,false,0,clock.sample(9_400_000_000L,true)),.5,"pause holds visual clock");pose(paused.sample(true,false,0,clock.sample(9_400_000_000L,false)),.5,"resume discards paused wall time");pose(paused.sample(true,false,0,clock.sample(9_800_000_000L,false)),1,"remaining eight ticks after resume");
        Object world=new Object();var pos=new BlockPos(8,80,8);pose(NativeCanopyVisualClock.sample(world,pos,false,false,0,0),0,"owner cache initial");NativeCanopyVisualClock.sample(world,pos,true,false,0,0);pose(NativeCanopyVisualClock.sample(world,pos.immutable(),true,false,0,8),.5,"replacement at same world position retains pose");pose(NativeCanopyVisualClock.sample(world,pos,true,false,0,8),.5,"repeated packet does not restart");for(int i=0;i<2048;i++)NativeCanopyVisualClock.sample(world,new BlockPos(i,0,0),false,false,0,8);need(NativeCanopyVisualClock.retained(world)==1024,"bounded owner cache");NativeCanopyVisualClock.clear(world);need(NativeCanopyVisualClock.retained(world)==0,"world unload retirement");
        var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId();NativeCanopyVisualClock.sample(world,pos,true,false,1,8);for(int i=0;i<10000;i++)NativeCanopyVisualClock.sample(world,pos,true,false,1,8);long before=bean.getThreadAllocatedBytes(thread);for(int i=0;i<10000;i++)NativeCanopyVisualClock.sample(world,pos,true,false,1,8);need(bean.getThreadAllocatedBytes(thread)-before==0,"warmed same-owner samples allocate zero bytes");NativeCanopyVisualClock.clear(world);System.out.println("Canopy animation PASS checks="+checks+" warmedSamples=10000 allocated=0");
    }
}
